SELECT

FROM RwaInstSpvProductRealizedIncome a WHERE 1 = 1

    AND a.userId = #{userId}


    AND a.instSpvProductId = #{instSpvProductId}


    AND a.incomeDistributionDate = #{incomeDistributionDate}


    AND a.incomeAmount = #{incomeAmount}


    AND a.incomeCurrency = #{incomeCurrency}


    AND a.remark = #{remark}


    AND a.createTime = #{createTime}


    AND a.updateBy = #{updateBy}


    AND a.updateTime = #{updateTime}

limit 1

SELECT

FROM RwaInstSpvProductRealizedIncome a WHERE 1 = 1

    AND a.userId = #{userId}


    AND a.instSpvProductId = #{instSpvProductId}


    AND a.incomeDistributionDate = #{incomeDistributionDate}


    AND a.incomeAmount = #{incomeAmount}


    AND a.incomeCurrency LIKE CONCAT('%',#{incomeCurrency}, '%')


    AND a.remark LIKE CONCAT('%',#{remark}, '%')


    AND a.createTime = #{createTime}


    AND a.updateBy LIKE CONCAT('%',#{updateBy}, '%')


    AND a.updateTime = #{updateTime}
